async (page) => {
  await page.locator('[data-slot="hover-card-trigger"]').hover();
  await page.waitForTimeout(400);
  const state = await page.evaluate(() => {
    const content = document.querySelector('[data-slot="hover-card-content"]');
    if (!content) return { contentExists: false };
    const cs = getComputedStyle(content);
    const rect = content.getBoundingClientRect();
    const wrapper = content.parentElement;
    const wcs = wrapper ? getComputedStyle(wrapper) : null;
    return {
      contentExists: true,
      state: content.getAttribute('data-state'),
      rect: rect.toJSON(),
      opacity: cs.opacity,
      visibility: cs.visibility,
      zIndex: cs.zIndex,
      wrapperTag: wrapper?.tagName,
      wrapperStyle: wrapper?.getAttribute('style'),
      wrapperZ: wcs?.zIndex,
      topAtPoint: (() => {
        const el = document.elementFromPoint(rect.x + rect.width / 2, rect.y + rect.height / 2);
        return el ? el.tagName + '.' + (el.className || '').toString().slice(0, 60) : null;
      })(),
    };
  });
  await page.screenshot({ path: './hover-open-tight.png', scale: 'css', type: 'png' });
  return state;
}

