async (page) => {
  const results = {};
  for (const combo of [
    { name: 'dark', colorScheme: 'dark', reducedMotion: 'no-preference' },
    { name: 'light-reduced', colorScheme: 'light', reducedMotion: 'reduce' },
    { name: 'dark-reduced', colorScheme: 'dark', reducedMotion: 'reduce' },
  ]) {
    await page.emulateMedia({ colorScheme: combo.colorScheme, reducedMotion: combo.reducedMotion });
    await page.reload({ waitUntil: 'networkidle' }).catch(() => page.waitForTimeout(3000));
    await page.mouse.move(10, 10);
    await page.waitForTimeout(200);
    await page.locator('[data-slot="hover-card-trigger"]').hover();
    await page.waitForTimeout(500);
    const state = await page.evaluate(() => {
      const content = document.querySelector('[data-slot="hover-card-content"]');
      if (!content) return { contentExists: false };
      const cs = getComputedStyle(content);
      return {
        contentExists: true,
        state: content.getAttribute('data-state'),
        opacity: cs.opacity,
        bg: cs.backgroundColor,
        color: cs.color,
        rectTop: content.getBoundingClientRect().top,
      };
    });
    await page.screenshot({ path: `./hover-${combo.name}.png`, scale: 'css', type: 'png' });
    results[combo.name] = state;
  }
  await page.emulateMedia({ colorScheme: null, reducedMotion: null });
  return results;
}

